const params = {};
const fields = $.input.fields || '*navigable';
params.fields = fields;
if ($.input.expand) params.expand = $.input.expand;
return { params };

const resp = $.steps.getIssue.response || {};
const f = resp.fields || {};

// Extract plain text from ADF body
function adfToText(adf) {
  if (!adf || !adf.content) return '';
  return adf.content.map(block => {
    if (block.content) return block.content.map(node => node.text || '').join('');
    return '';
  }).join('\n');
}

const description = typeof f.description === 'string'
  ? f.description
  : adfToText(f.description);

const comments = (f.comment && f.comment.comments || []).slice(-5).map(c => ({
  id: c.id,
  author: c.author ? c.author.displayName : '',
  body: typeof c.body === 'string' ? c.body : adfToText(c.body),
  created: c.created
}));

return {
  id: resp.id || '',
  key: resp.key || '',
  self: resp.self || '',
  summary: f.summary || '',
  status: f.status ? f.status.name : '',
  statusCategory: f.status && f.status.statusCategory ? f.status.statusCategory.name : '',
  assignee: f.assignee ? f.assignee.displayName : 'Unassigned',
  assigneeAccountId: f.assignee ? f.assignee.accountId : null,
  reporter: f.reporter ? f.reporter.displayName : '',
  priority: f.priority ? f.priority.name : '',
  issueType: f.issuetype ? f.issuetype.name : '',
  project: f.project ? { key: f.project.key, name: f.project.name } : {},
  description: description.length > 2000 ? description.substring(0, 2000) + '...' : description,
  labels: f.labels || [],
  created: f.created || '',
  updated: f.updated || '',
  resolution: f.resolution ? f.resolution.name : null,
  recentComments: comments,
  transitions: resp.transitions || [],
  summary_text: `${resp.key}: "${f.summary || ''}" [${f.status ? f.status.name : 'unknown'}] assigned to ${f.assignee ? f.assignee.displayName : 'nobody'}`
};
